            const requestUrl = await this._buildTableUrl(tableName, connectionReference, `/${id}`);
            const result = await dataClient.updateDataAsync(requestUrl, connectionReference.apiId, connectionReference.connectionId ?? '', tableName, data, ConnectorOperationName.UpdateRecord);
            return result;
